begin;
create table real_estate.properties (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete restrict, company_id uuid not null references platform.companies(id) on delete restrict, name text not null, property_code text not null, status text not null default 'active' check (status in ('active','inactive','archived')), address jsonb not null default '{}', created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique (organization_id, company_id, property_code), unique (organization_id, id), foreign key (organization_id, company_id) references platform.companies(organization_id, id));
create table real_estate.units (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete restrict, company_id uuid not null references platform.companies(id) on delete restrict, property_id uuid not null, unit_number text not null, unit_type text, monthly_rent_minor bigint not null default 0 check (monthly_rent_minor >= 0), status text not null default 'vacant' check (status in ('vacant','reserved','occupied','maintenance','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, property_id, unit_number), foreign key (organization_id, company_id) references platform.companies(organization_id, id), foreign key (organization_id, property_id) references real_estate.properties(organization_id, id));
create table integrations.mpesa_accounts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete restrict, account_name text not null, shortcode text not null, account_type text not null check (account_type in ('business_one_account','paybill','till')), environment text not null check (environment in ('sandbox','production')), collection_enabled boolean not null default true, disbursement_enabled boolean not null default false, status text not null default 'pending' check (status in ('pending','active','suspended','retired')), secret_reference text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (shortcode, environment));
create table integrations.mpesa_callbacks (id uuid primary key default gen_random_uuid(), organization_id uuid references platform.organizations(id) on delete restrict, mpesa_account_id uuid references integrations.mpesa_accounts(id) on delete restrict, callback_type text not null, provider_request_id text, received_at timestamptz not null default now(), payload_hash text not null, raw_payload jsonb not null, processing_status text not null default 'received' check (processing_status in ('received','processed','duplicate','rejected','failed')), processed_at timestamptz, failure_reason text, unique (callback_type, payload_hash));
create table communications.conversations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete cascade, company_id uuid references platform.companies(id) on delete cascade, application_key text not null, subject text, status text not null default 'open' check (status in ('open','closed','archived')), created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table communications.messages (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete cascade, conversation_id uuid not null references communications.conversations(id) on delete cascade, sender_user_id uuid references auth.users(id) on delete set null, sender_type text not null check (sender_type in ('user','tenant','landlord','caretaker','system')), body text not null, created_at timestamptz not null default now(), deleted_at timestamptz);
commit;
